 }
 /* scroll-linked: progress, header, parallax, sticky cta */
 var bar=$('.syx-progress i'),hero=$('#syxHero'),heroBg=hero&&$('.bg',hero),
     onePic=$('.syx-one .pic .im'),sticky=$('#syxSticky'),contact=$('#contact'),lastY=0,tick=false;
 function onScroll(){
